@namespace sv_f907af3294374430a635faffbd0405b9.Components.Pages.Apply

<nav class="step-indicator" aria-label="Application progress">
    <ol class="step-list">
        @for (int i = 0; i < Steps.Length; i++)
        {
            var index = i;
            var stepClass = GetStepClass(index);
            <li class="step-item @stepClass"
                @onclick="() => OnStepClick(index)"
                role="button"
                aria-current="@(index == CurrentStep ? "step" : null)">
                <span class="step-marker">
                    @if (index < CurrentStep)
                    {
                        <span class="checkmark">&#10003;</span>
                    }
                    else
                    {
                        <span>@(index + 1)</span>
                    }
                </span>
                <span class="step-label">@Steps[index]</span>
            </li>
        }
    </ol>
</nav>

@code {
    private static readonly string[] Steps = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public EventCallback<int> OnStepSelected { get; set; }

    private string GetStepClass(int index)
    {
        if (index == CurrentStep) return "active";
        if (index < CurrentStep) return "completed";
        return "dimmed";
    }

    private async Task OnStepClick(int index)
    {
        if (index < CurrentStep)
        {
            await OnStepSelected.InvokeAsync(index);
        }
    }
}

@namespace sv_f907af3294374430a635faffbd0405b9.Components.Pages.Apply

<div class="step-form personal-info-step">
    <h2>Personal Information</h2>

    <div class="form-group">
        <label for="fullName">Full Name *</label>
        <input id="fullName" type="text" @bind="FullName" @bind:event="oninput" class="form-control" />
    </div>

    <div class="form-group">
        <label for="email">Email *</label>
        <input id="email" type="email" @bind="Email" @bind:event="oninput" class="form-control" />
        @if (!string.IsNullOrEmpty(emailError))
        {
            <span class="field-error">@emailError</span>
        }
    </div>

    <div class="form-group">
        <label for="phone">Phone *</label>
        <input id="phone" type="tel" @bind="Phone" @bind:event="oninput" class="form-control" />
    </div>

    <div class="form-group">
        <label for="address">Address *</label>
        <input id="address" type="text" @bind="Address" @bind:event="oninput" class="form-control" />
    </div>

    @if (!string.IsNullOrEmpty(validationError))
    {
        <div class="validation-error">@validationError</div>
    }

    <div class="step-actions">
        <button class="btn btn-primary" @onclick="HandleNext" disabled="@isValidating">
            @(isValidating ? "Validating..." : "Next")
        </button>
    </div>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter] public EventCallback<(string FullName, string Email, string Phone, string Address)> OnNext { get; set; }
    [Parameter] public Func<string, Task<bool>>? ValidateEmail { get; set; }

    private string? validationError;
    private string? emailError;
    private bool isValidating;

    private async Task HandleNext()
    {
        validationError = null;
        emailError = null;

        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email) ||
            string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
        {
            validationError = "All fields are required.";
            return;
        }

        if (ValidateEmail is not null)
        {
            isValidating = true;
            StateHasChanged();

            var isValid = await ValidateEmail(Email);
            isValidating = false;

            if (!isValid)
            {
                emailError = "Please enter a valid email address.";
                return;
            }
        }

        await OnNext.InvokeAsync((FullName, Email, Phone, Address));
    }
}

@namespace sv_f907af3294374430a635faffbd0405b9.Components.Pages.Apply

<div class="work-entry-form">
    <div class="entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (ShowRemove)
        {
            <button class="btn btn-danger btn-sm" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" value="@Entry.Company" @onchange="e => Update(e, nameof(Entry.Company))" class="form-control" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" value="@Entry.Title" @onchange="e => Update(e, nameof(Entry.Title))" class="form-control" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@Entry.StartDate.ToString("yyyy-MM-dd")" @onchange="e => UpdateStartDate(e)" class="form-control" />
        </div>

        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@Entry.EndDate?.ToString("yyyy-MM-dd")" @onchange="e => UpdateEndDate(e)" class="form-control" disabled="@IsCurrent" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent" @onchange="HandleCurrentToggle" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea value="@Entry.Description" @onchange="e => Update(e, nameof(Entry.Description))" class="form-control" rows="3"></textarea>
    </div>
</div>

@code {
    [Parameter] public WorkEntryModel Entry { get; set; } = new();
    [Parameter] public int Index { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryModel> OnChanged { get; set; }

    private bool IsCurrent => Entry.IsCurrent;

    private void Update(ChangeEventArgs e, string field)
    {
        var val = e.Value?.ToString() ?? "";
        var updated = field switch
        {
            nameof(Entry.Company) => Entry with { Company = val },
            nameof(Entry.Title) => Entry with { Title = val },
            nameof(Entry.Description) => Entry with { Description = val },
            _ => Entry
        };
        OnChanged.InvokeAsync(updated);
    }

    private void UpdateStartDate(ChangeEventArgs e)
    {
        if (DateTime.TryParse(e.Value?.ToString(), out var date))
        {
            OnChanged.InvokeAsync(Entry with { StartDate = date });
        }
    }

    private void UpdateEndDate(ChangeEventArgs e)
    {
        DateTime? date = DateTime.TryParse(e.Value?.ToString(), out var d) ? d : null;
        OnChanged.InvokeAsync(Entry with { EndDate = date });
    }

    private void HandleCurrentToggle(ChangeEventArgs e)
    {
        var isCurrent = (bool)(e.Value ?? false);
        OnChanged.InvokeAsync(Entry with { IsCurrent = isCurrent, EndDate = isCurrent ? null : Entry.EndDate });
    }

    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }
}

@namespace sv_f907af3294374430a635faffbd0405b9.Components.Pages.Apply

<div class="step-form work-history-step">
    <h2>Work History</h2>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <WorkEntryForm Entry="@Entries[index]"
                       Index="index"
                       ShowRemove="@(Entries.Count > 1)"
                       OnRemove="() => RemoveEntry(index)"
                       OnChanged="(entry) => UpdateEntry(index, entry)" />
    }

    <button class="btn btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    @if (!string.IsNullOrEmpty(validationError))
    {
        <div class="validation-error">@validationError</div>
    }

    <div class="step-actions">
        <button class="btn btn-outline" @onclick="OnBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<WorkEntryForm.WorkEntryModel> Entries { get; set; } = new();
    [Parameter] public EventCallback<List<WorkEntryForm.WorkEntryModel>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? validationError;

    private void AddEntry()
    {
        Entries.Add(new WorkEntryForm.WorkEntryModel());
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
        {
            Entries.RemoveAt(index);
        }
    }

    private void UpdateEntry(int index, WorkEntryForm.WorkEntryModel entry)
    {
        Entries[index] = entry;
    }

    private async Task HandleNext()
    {
        validationError = null;

        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                validationError = "Company name and job title are required for all entries.";
                return;
            }
        }

        await OnNext.InvokeAsync(Entries);
    }
}

@namespace sv_f907af3294374430a635faffbd0405b9.Components.Pages.Apply

<div class="reference-form">
    <h4>Reference @(Index + 1)</h4>

    @if (ShowRemove)
    {
        <button class="btn btn-danger btn-sm" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
    }

    <div class="form-group">
        <label>Name *</label>
        <input type="text" value="@Ref.Name" @onchange="e => Update(nameof(ReferenceModel.Name), e)" class="form-control" />
    </div>

    <div class="form-group">
        <label>Relationship *</label>
        <input type="text" value="@Ref.Relationship" @onchange="e => Update(nameof(ReferenceModel.Relationship), e)" class="form-control" />
