@namespace sv_f907af3294374430a635faffbd0405b9.Components.Pages.Apply

<div class="reference-form">
    <h4>Reference @(Index + 1)</h4>

    @if (ShowRemove)
    {
        <button class="btn btn-danger btn-sm" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
    }

    <div class="form-group">
        <label>Name *</label>
        <input type="text" value="@Ref.Name" @onchange="e => Update(nameof(ReferenceModel.Name), e)" class="form-control" />
    </div>

    <div class="form-group">
        <label>Relationship *</label>
        <input type="text" value="@Ref.Relationship" @onchange="e => Update(nameof(ReferenceModel.Relationship), e)" class="form-control" />
    </div>

    <div class="form-group">
        <label>Email *</label>
        <input type="email" value="@Ref.Email" @onchange="e => Update(nameof(ReferenceModel.Email), e)" class="form-control" />
    </div>

    <div class="form-group">
        <label>Phone</label>
        <input type="tel" value="@Ref.Phone" @onchange="e => Update(nameof(ReferenceModel.Phone), e)" class="form-control" />
    </div>
</div>

@code {
    [Parameter] public ReferenceModel Ref { get; set; } = new();
    [Parameter] public int Index { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<ReferenceModel> OnChanged { get; set; }

    private void Update(string field, ChangeEventArgs e)
    {
        var val = e.Value?.ToString() ?? "";
        var updated = field switch
        {
            nameof(ReferenceModel.Name) => Ref with { Name = val },
            nameof(ReferenceModel.Relationship) => Ref with { Relationship = val },
            nameof(ReferenceModel.Email) => Ref with { Email = val },
            nameof(ReferenceModel.Phone) => Ref with { Phone = val },
            _ => Ref
        };
        OnChanged.InvokeAsync(updated);
    }

    public record ReferenceModel
    {
        public string Name { get; init; } = "";
        public string Relationship { get; init; } = "";
        public string Email { get; init; } = "";
        public string Phone { get; init; } = "";
    }
}

