toolArgs.file_text:
.apply-page {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem 1rem;
}

.apply-page h1 {
    text-align: center;
    margin-bottom: 2rem;
    color: #1a1a2e;
}

/* Step Indicator */
.step-indicator {
    margin-bottom: 2rem;
}

.step-list {
    display: flex;
    list-style: none;
    padding: 0;
    margin: 0;
    justify-content: space-between;
}

.step-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    flex: 1;
    position: relative;
    cursor: default;
}

.step-item.completed {
    cursor: pointer;
}

.step-marker {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    margin-bottom: 0.5rem;
    border: 2px solid #ccc;
    background: #fff;
    color: #999;
    transition: all 0.2s;
}

.step-item.active .step-marker {
    background: #4361ee;
    border-color: #4361ee;
    color: #fff;
}

.step-item.completed .step-marker {
    background: #2ec4b6;
    border-color: #2ec4b6;
    color: #fff;
}

.step-item.dimmed .step-marker {
    opacity: 0.5;
}

.step-label {
    font-size: 0.75rem;
    text-align: center;
    color: #666;
}

.step-item.active .step-label {
    color: #4361ee;
    font-weight: 600;
}

.step-item.completed .step-label {
    color: #2ec4b6;
}

.step-item.dimmed .step-label {
    opacity: 0.5;
}

.checkmark {
    font-size: 1rem;
}

/* Form styles */
.step-form {
    background: #fff;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 2rem;
}

.step-form h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    color: #1a1a2e;
}

.step-description {
    color: #666;
    margin-bottom: 1.5rem;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.25rem;
    font-weight: 500;
    color: #333;
    font-size: 0.9rem;
}

.form-control {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 1rem;
    box-sizing: border-box;
    transition: border-color 0.2s;
}

.form-control:focus {
    outline: none;
    border-color: #4361ee;
    box-shadow: 0 0 0 2px rgba(67, 97, 238, 0.1);
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.checkbox-label {
    display: inline-flex !important;
    align-items: center;
    gap: 0.5rem;
    font-weight: normal !important;
    margin-top: 0.5rem;
    cursor: pointer;
}

.checkbox-label input[type="checkbox"] {
    width: auto;
}

/* Buttons */
.step-actions {
    display: flex;
    justify-content: space-between;
    margin-top: 2rem;
    padding-top: 1.5rem;
    border-top: 1px solid #eee;
}

.btn {
    padding: 0.6rem 1.5rem;
    border: none;
    border-radius: 4px;
    font-size: 1rem;
    cursor: pointer;
    transition: background 0.2s, opacity 0.2s;
}

.btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-primary {
    background: #4361ee;
    color: #fff;
    margin-left: auto;
}

.btn-primary:hover:not(:disabled) {
    background: #3a56d4;
}

.btn-outline {
    background: transparent;
    border: 1px solid #ccc;
    color: #333;
}

.btn-outline:hover {
    background: #f5f5f5;
}

.btn-secondary {
    background: #f0f0f0;
    color: #333;
    margin-bottom: 1rem;
}

.btn-secondary:hover {
    background: #e0e0e0;
}

.btn-danger {
    background: #e63946;
    color: #fff;
}

.btn-danger.btn-sm {
    padding: 0.3rem 0.8rem;
    font-size: 0.8rem;
}

.btn-link {
    background: none;
    border: none;
    color: #4361ee;
    cursor: pointer;
    text-decoration: underline;
    font-size: 0.9rem;
    padding: 0;
}

.btn-link:hover {
    color: #3a56d4;
}

.btn-submit {
    padding: 0.8rem 2rem;
    font-size: 1.1rem;
}

/* Validation */
.validation-error {
    color: #e63946;
    background: #fdecea;
    border: 1px solid #f5c6cb;
    border-radius: 4px;
    padding: 0.75rem;
    margin-top: 1rem;
    font-size: 0.9rem;
}

.field-error {
    color: #e63946;
    font-size: 0.8rem;
    margin-top: 0.25rem;
    display: block;
}

/* Work entry */
.work-entry-form {
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    padding: 1.5rem;
    margin-bottom: 1rem;
    background: #fafafa;
}

.entry-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.entry-header h4 {
    margin: 0;
    color: #333;
}

/* Reference form */
.reference-form {
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    padding: 1.5rem;
    margin-bottom: 1rem;
    background: #fafafa;
    position: relative;
}

.reference-form h4 {
    margin-top: 0;
    margin-bottom: 1rem;
}

.reference-form .btn-danger {
    position: absolute;
    top: 1rem;
    right: 1rem;
}

/* Cover letter */
.cover-letter-textarea {
    resize: vertical;
    min-height: 200px;
}

.char-count {
    display: block;
    text-align: right;
    font-size: 0.8rem;
    color: #666;
    margin-top: 0.25rem;
}

.char-count-warning {
    color: #e63946;
}

/* Review step */
.review-section {
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    padding: 1.5rem;
    margin-bottom: 1rem;
}

.review-section-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.review-section-header h3 {
    margin: 0;
    color: #1a1a2e;
}

.review-section dl {
    display: grid;
    grid-template-columns: auto 1fr;
    gap: 0.5rem 1rem;
    margin: 0;
}

.review-section dt {
    font-weight: 600;
    color: #555;
}

.review-section dd {
    margin: 0;
    color: #333;
}

.review-work-entry {
    margin-bottom: 1rem;
    padding-bottom: 1rem;
    border-bottom: 1px solid #eee;
}

.review-work-entry:last-child {
    border-bottom: none;
    margin-bottom: 0;
    padding-bottom: 0;
}

.date-range {
    color: #666;
    font-size: 0.9rem;
}

.review-reference {
    margin-bottom: 0.75rem;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: #f9f9f9;
    padding: 1rem;
    border-radius: 4px;
    border: 1px solid #eee;
}

/* Submission confirmation */
.submission-confirmation {
    text-align: center;
    padding: 3rem 2rem;
}

.submission-confirmation h2 {
    color: #2ec4b6;
    font-size: 1.8rem;
}

.application-id {
    font-size: 1.5rem;
    color: #4361ee;
    margin: 1.5rem 0;
}

